#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353LL;
        long long value;

        Mod998() : value(0) {}
        Mod998(long long v) : value((v % MOD + MOD) % MOD) {}

        static long long modinv(long long a, long long m) {
            long long m0 = m, t, q;
            long long x0 = 0, x1 = 1;
            if (m == 1) return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m; a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0) x1 += m0;
            return x1;
        }

        static long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        static long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        static long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }

        long long inv() const {
            return modinv(value, MOD);
        }

        static long long ncr(long long n, long long r, vector<long long>& fact, vector<long long>& invFact) {
            if (r < 0 || r > n) return 0;
            return mult(fact[n], mult(invFact[r], invFact[n - r]));
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    using Mod = NumberTheory::Mod998;
    vector<long long> fact(n + m + 1, 1);
    vector<long long> invFact(n + m + 1, 1);

    // Precompute factorials
    for (int i = 1; i <= n + m; i++) {
        fact[i] = Mod::mult(fact[i - 1], i);
    }
    invFact[n + m] = Mod::modinv(fact[n + m], Mod::MOD);
    for (int i = n + m - 1; i >= 0; i--) {
        invFact[i] = Mod::mult(invFact[i + 1], i + 1);
    }

    // Function to compute nCr
    auto ncr = [&](long long n, long long r) {
        return Mod::ncr(n, r, fact, invFact);
    };

    // Compute phaseSize
    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long denom = modinv(n + m - i, Mod::MOD);
        p = Mod::mult(p, n - i);
        p = Mod::mult(p, denom);
        phaseSize = Mod::add(phaseSize, p);
        if (i >= n || n - i <= 0) break; // prevent infinite loop
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = Mod::mult(m + k, modinv(k, Mod::MOD));
        long long term = Mod::mult(ncr(n, k), numPhases);
        term = Mod::mult(term, phaseSize);
        if (k % 2 == 1)
            answer = Mod::add(answer, term);
        else
            answer = Mod::subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
